static int env_append(const char *varname, const char *varvalue)
{
	int len = 0;
	char *oldvalue, *newvalue;

	debug("%s: varvalue = %s\n", __func__, varvalue);

	/* before import into hashtable */
	if (!(gd->flags & GD_FLG_ENV_READY) || !varname)
		return 1;

	if (env_exist(varname, varvalue))
		return 0;

	debug("%s: reall append: %s\n", __func__, varvalue);

	if (varvalue)
		len += strlen(varvalue);

	oldvalue = env_get(varname);
	if (oldvalue)
		len += strlen(oldvalue);

	newvalue = malloc(len + 2);
	if (!newvalue)
	{
		printf("Error: malloc in %s failed!\n", __func__);
		return 1;
	}

	*newvalue = '\0';

	if (oldvalue)
	{
		strcpy(newvalue, oldvalue);
		strcat(newvalue, " ");
	}

	if (varvalue)
		strcat(newvalue, varvalue);

	debug("%s: newvalue: %s\n", __func__, newvalue);
	env_set(varname, newvalue);
	free(newvalue);

	return 0;
}

static int dfsetEnv(void)
{
	int count = 0;

	env_set("recover", "0");

	gpio_request(BOARD_RST, "RST_CHECK");
	gpio_direction_input(BOARD_RST);

	udelay(20000);
	if (gpio_get_value(BOARD_RST) != 0)
		goto rst_done;

	udelay(50000);
	if (gpio_get_value(BOARD_RST) != 0)
		goto rst_done;

	while (gpio_get_value(BOARD_RST) == 0) {
		udelay(100000);
		count++;
		if (count >= 100) {
			printf("-----------------RECOVER-------------------\n");
			env_set("recover", "1");
			break;
		}
	}

rst_done:
	env_set("fdtcontroladdr", "0x1f5080c8");
	/* sdfwupdate 由 Loader ATAG / misc 写入，勿在此覆盖 bootargs */

	gpio_free(BOARD_RST);
	return 0;
}



void writeCmd(const uint8_t *cmd,uint8_t len){

    gpio_direction_output(TFT_DC,0);
	spi_xfer(slave, len*8, cmd, din,
		       SPI_XFER_BEGIN | SPI_XFER_END);
    

}

void writeData(const uint8_t *data,uint32_t len){

     gpio_direction_output(TFT_DC,1);
     spi_xfer(slave, len*8, data, din,
		       SPI_XFER_BEGIN | SPI_XFER_END);
}
